import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    active = df[~df['row_kind'].isin(['cancelled', 'canceled', 'cancel', 'void', 'voided'])].copy()
    active_dwell = active[active['dwell_hours'] >= 0].copy()

    facility_dwell = (
        active_dwell.groupby('Facility')['dwell_hours']
        .sum()
        .reset_index()
    )
    facility_counts = (
        active_dwell.groupby('Facility')['Appointment ID']
        .nunique()
        .reset_index()
        .rename(columns={'Appointment ID': 'appt_count'})
    )
    facility_avg = facility_dwell.merge(facility_counts, on='Facility')
    facility_avg['avg_dwell'] = facility_avg['dwell_hours'] / facility_avg['appt_count']
    facility_avg = facility_avg.sort_values('avg_dwell', ascending=False)

    result['segments'].append({
        "segment_column": "Facility",
        "metric_column": "dwell_hours",
        "aggregation": "ratio",
        "label": "avg_dwell",
        "results": [
            {"name": str(row['Facility']), "value": round(float(row['avg_dwell']), 4)}
            for _, row in facility_avg.iterrows()
        ]
    })
except Exception as e:
    result['segments'].append({
        "segment_column": "Facility",
        "metric_column": "dwell_hours",
        "aggregation": "ratio",
        "label": "avg_dwell",
        "results": [{"name": "error", "value": 0.0}]
    })

try:
    direction_dwell_sum = active_dwell.groupby('Direction')['dwell_hours'].sum().reset_index()
    direction_counts = active_dwell.groupby('Direction')['Appointment ID'].nunique().reset_index().rename(columns={'Appointment ID': 'appt_count'})
    direction_avg = direction_dwell_sum.merge(direction_counts, on='Direction')
    direction_avg['avg_dwell'] = direction_avg['dwell_hours'] / direction_avg['appt_count']
    direction_avg = direction_avg.sort_values('avg_dwell', ascending=False)

    result['segments'].append({
        "segment_column": "Direction",
        "metric_column": "dwell_hours",
        "aggregation": "ratio",
        "label": "avg_dwell_by_direction",
        "results": [
            {"name": str(row['Direction']), "value": round(float(row['avg_dwell']), 4)}
            for _, row in direction_avg.iterrows()
        ]
    })
except Exception:
    pass

try:
    fac_dir_sum = active_dwell.groupby(['Facility', 'Direction'])['dwell_hours'].sum().reset_index()
    fac_dir_counts = active_dwell.groupby(['Facility', 'Direction'])['Appointment ID'].nunique().reset_index().rename(columns={'Appointment ID': 'appt_count'})
    fac_dir = fac_dir_sum.merge(fac_dir_counts, on=['Facility', 'Direction'])
    fac_dir['avg_dwell'] = fac_dir['dwell_hours'] / fac_dir['appt_count']
    fac_dir = fac_dir.sort_values('avg_dwell', ascending=False).head(10)

    result['segments'].append({
        "segment_column": "Facility|Direction",
        "metric_column": "dwell_hours",
        "aggregation": "ratio",
        "label": "avg_dwell_facility_direction",
        "results": [
            {"name": f"{row['Facility']}|{row['Direction']}", "value": round(float(row['avg_dwell']), 4)}
            for _, row in fac_dir.iterrows()
        ]
    })
except Exception:
    pass

try:
    carrier_dwell_sum = active_dwell.groupby('Carrier')['dwell_hours'].sum().reset_index()
    carrier_counts = active_dwell.groupby('Carrier')['Appointment ID'].nunique().reset_index().rename(columns={'Appointment ID': 'appt_count'})
    carrier_avg = carrier_dwell_sum.merge(carrier_counts, on='Carrier')
