            {"name": str(row['Carrier']), "value": round(float(row['avg_dwell']), 4)}
            for _, row in carrier_avg.iterrows()
        ]
    })
except Exception:
    pass

result['assumptions'].append("avg_dwell = sum(dwell_hours where dwell_hours>=0) / count(distinct Appointment ID where dwell_hours>=0), per domain rules")
result['assumptions'].append("38 cancelled rows excluded; 3 out-of-range dwell_hours rows excluded from dwell calculations")
result['assumptions'].append("dwell_hours column used as-is from data; not recomputed")

